"use strict";

const stages = [
  { name: "Intake", icon: "inbox", action: "Review new orders", next: "To proofing" },
  { name: "Proofing", icon: "proof", action: "Check or approve proofs", next: "Mark ready" },
  { name: "Ready to Print", icon: "printer", action: "Start print runs", next: "Start printing" },
  { name: "Printing", icon: "clock", action: "Finish print runs", next: "To pickup" },
  { name: "Pickup", icon: "bag", action: "Hand over copies" },
];

const icons = {
  layers: '<path d="m12 3 9 5-9 5-9-5 9-5Zm-9 9 9 5 9-5M3 16l9 5 9-5"/>',
  printer: '<path d="M6 9V3h12v6M6 17H4a2 2 0 0 1-2-2v-4a2 2 0 0 1 2-2h16a2 2 0 0 1 2 2v4a2 2 0 0 1-2 2h-2"/><path d="M6 14h12v7H6zm12-2h1"/>',
  plus: '<path d="M12 5v14M5 12h14"/>',
  bag: '<rect x="4" y="7" width="16" height="14" rx="2"/><path d="M8 9V6a4 4 0 0 1 8 0v3"/>',
  alert: '<circle cx="12" cy="12" r="9"/><path d="M12 7v5m0 4h.01"/>',
  copy: '<rect x="8" y="8" width="12" height="13" rx="2"/><path d="M16 5a2 2 0 0 0-2-2H6a2 2 0 0 0-2 2v10a2 2 0 0 0 2 2"/>',
  board: '<rect x="3" y="4" width="18" height="16" rx="2"/><path d="M9 4v16m6-16v16"/>',
  list: '<path d="M8 6h12M8 12h12M8 18h12M4 6h.01M4 12h.01M4 18h.01"/>',
  search: '<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 4 4"/>',
  inbox: '<path d="M3 13l3-8h12l3 8v5a1 1 0 0 1-1 1H4a1 1 0 0 1-1-1Zm0 0h5l2 3h4l2-3h5"/>',
  proof: '<path d="M5 3h9l5 5v13H5zm9 0v5h5m-10 6 2 2 4-4"/>',
  clock: '<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',
  calendar: '<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4m10-4v4M3 10h18"/>',
  back: '<path d="M19 12H5m7 7-7-7 7-7"/>',
  forward: '<path d="M5 12h14m-7-7 7 7-7 7"/>',
  device: '<rect x="3" y="4" width="18" height="13" rx="2"/><path d="M8 21h8m-4-4v4"/>',
  close: '<path d="m6 6 12 12M18 6 6 18"/>',
};

const storageKey = "copy-desk.orders.v1";
const $ = (id) => document.getElementById(id);
const number = new Intl.NumberFormat("en");
const fullDay = new Intl.DateTimeFormat("en-GB", { weekday: "long", day: "numeric", month: "long", year: "numeric" });
const shortDay = new Intl.DateTimeFormat("en-GB", { weekday: "short", day: "numeric", month: "short" });
const timestamp = new Intl.DateTimeFormat("en-GB", { day: "numeric", month: "short", year: "numeric", hour: "2-digit", minute: "2-digit", hourCycle: "h23" });
const jobDialog = $("job-dialog");
const pickupDialog = $("pickup-dialog");
const jobForm = $("job-form");
const pickupForm = $("pickup-form");
let jobs = [];
let editing = null;
let collecting = null;
let noticeTimer;
let lastRenderAt;

function icon(name) {
  return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]}</svg>`;
}

function escapeHtml(value) {
  const replacements = { "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" };
  return String(value).replace(/[&<>"']/g, (char) => replacements[char]);
}

function dateKey(date) {
  const pad = (value) => String(value).padStart(2, "0");
  return `${String(date.getFullYear()).padStart(4, "0")}-${pad(date.getMonth() + 1)}-${pad(date.getDate())}`;
}

function seedOrders(now) {
  const monday = new Date(now.getFullYear(), now.getMonth(), now.getDate() - ((now.getDay() + 6) % 7));
  const tuesday = new Date(monday.getFullYear(), monday.getMonth(), monday.getDate() + 1);
  const wednesday = new Date(monday.getFullYear(), monday.getMonth(), monday.getDate() + 2);
  return [
    { id: 1, title: "Recital program", quantity: 75, stage: 1, due: dateKey(tuesday) + "T15:00" },
    { id: 2, title: "Museum flyer", quantity: 200, stage: 2, due: dateKey(wednesday) + "T10:00" },
    { id: 3, title: "Class booklet", quantity: 30, stage: 4, due: dateKey(tuesday) + "T12:00" },
  ].map((job) => ({ ...job, notes: "", pickups: [] }));
}

function handedOver(job) {
  return job.pickups.reduce((total, pickup) => total + pickup.copies, 0);
}

function outstanding(job) {
  return job.quantity - handedOver(job);
}

function isOverdue(job, now) {
  return outstanding(job) > 0 && new Date(job.due).getTime() < now.getTime();
}

function ref(job) {
  return "#" + String(job.id).padStart(3, "0");
}

function dueText(job, includeYear = false) {
  const date = new Date(job.due);
  const day = includeYear || date.getFullYear() !== new Date().getFullYear()
    ? shortDay.format(date) + " " + date.getFullYear()
    : shortDay.format(date);
  return `${day} · ${job.due.slice(11)}`;
}

function readOrders() {
  const raw = localStorage.getItem(storageKey);
  if (raw === null) return null;
  const saved = JSON.parse(raw);
  if (!Array.isArray(saved)) throw new Error("Invalid board data");
  return saved;
}

function setStorageStatus(ok) {
  const status = $("local-status");
  status.classList.toggle("error", !ok);
  status.innerHTML = ok ? "<i></i> Offline workspace" : "<i></i> Local storage unavailable";
  document.querySelector(".footer span").innerHTML = icon("device") + (ok
    ? " Orders are saved in this browser."
    : " Order changes require browser storage. Check your browser settings and reopen the board.");
}

function initialize() {
  try {
    const saved = readOrders();
    jobs = saved ?? seedOrders(new Date());
    if (saved === null) localStorage.setItem(storageKey, JSON.stringify(jobs));
  } catch {
    setStorageStatus(false);
  }
}

function refreshOrders() {
  try {
    const saved = readOrders();
    if (saved !== null) jobs = saved;
    render();
  } catch {
    setStorageStatus(false);
  }
}

function report(message) {
  const notice = $("notice");
  clearTimeout(noticeTimer);
  notice.textContent = message;
  notice.hidden = false;
  noticeTimer = setTimeout(() => { notice.hidden = true; }, 4500);
}

function updateOrders(update, submitButton = null) {
  // Serialize writes across tabs when the browser supports Web Locks.
  const save = () => {
    let current;
    try {
      current = readOrders() ?? jobs;
    } catch {
      setStorageStatus(false);
      throw new Error("Could not read the saved board. Check browser storage and try again.");
    }
    const updated = update(current);
    try {
      localStorage.setItem(storageKey, JSON.stringify(updated));
    } catch {
      setStorageStatus(false);
      throw new Error("Could not save the change. Check browser storage and try again.");
    }
    jobs = updated;
    setStorageStatus(true);
  };

  if (submitButton) submitButton.disabled = true;
  return Promise.resolve().then(async () => {
    try {
      if (navigator.locks) return await navigator.locks.request(storageKey, save);
    } catch (error) {
      // Some browsers allow local storage on file URLs but restrict Web Locks.
      if (error.name !== "SecurityError") throw error;
    }
    return save();
  }).finally(() => {
    if (submitButton) submitButton.disabled = false;
  });
}

function card(job, now) {
  const left = outstanding(job);
  const late = isOverdue(job, now);
  const backLabel = job.stage > 0 ? "Move back to " + stages[job.stage - 1].name : "";
  const previous = backLabel ? `<button type="button" class="icon-button" data-action="back" title="${backLabel}" aria-label="${backLabel} for ${escapeHtml(job.title)}">${icon("back")}</button>` : "";
  const next = job.stage < stages.length - 1
    ? `<button type="button" class="button secondary" data-action="next" title="Move to ${stages[job.stage + 1].name}">${stages[job.stage].next} ${icon("forward")}</button>`
    : `<button type="button" class="button handover" data-action="pickup">${icon("bag")} Record pickup</button>`;
  return `<article class="job-card${late ? " late" : ""}" data-job="${job.id}">
    <div class="job-body">
      <div class="job-meta"><span class="job-ref">${ref(job)}</span>${late ? `<span class="late-label">${icon("alert")} Overdue</span>` : ""}${left === 0 ? '<span class="job-ref">Picked up</span>' : ""}</div>
      <h3 class="job-title"><button type="button" class="title-button" data-action="edit" title="Edit job">${escapeHtml(job.title)}</button></h3>
      <div class="due">${icon("calendar")}<time datetime="${job.due}" title="${dueText(job, true)}">${dueText(job)}</time></div>
      <div class="quantity"><div><span>Ordered</span><strong>${number.format(job.quantity)}</strong></div><div><span>Outstanding</span><strong>${number.format(left)}</strong></div></div>
    </div>
    ${left > 0 ? `<div class="card-actions">${previous}${next}</div>` : ""}
  </article>`;
}

function compareOrders(a, b) {
  return a.due.localeCompare(b.due) || a.id - b.id;
}

function renderBoard(now) {
  const board = $("board");
  const active = document.activeElement;
  const focused = active?.closest("#board [data-job]")?.dataset.job;
  const focusedAction = focused && active.dataset.action;
  const filter = $("filter").value;
  const query = $("search").value.trim().toLowerCase();
  const today = dateKey(now);
  const matches = jobs.filter((job) => {
    if (query && !`${job.title} ${ref(job)} ${job.notes}`.toLowerCase().includes(query)) return false;
    if (filter === "complete") return outstanding(job) === 0;
    if (outstanding(job) === 0) return false;
    if (filter === "today") return job.due.startsWith(today + "T");
    if (filter === "overdue") return isOverdue(job, now);
    return true;
  }).sort(compareOrders);

  if (filter === "complete") {
    board.innerHTML = '<h2 class="completed-title">Completed jobs</h2>' + (matches.length
      ? `<div class="completed-grid">${matches.map((job) => card(job, now)).join("")}</div>`
      : '<p class="section-empty">No completed jobs match this view.</p>');
  } else {
    board.innerHTML = `<div class="board-grid">${stages.map((stage, index) => {
      const group = matches.filter((job) => job.stage === index);
      return `<section class="lane stage-${index}" aria-labelledby="stage-${index}">
        <div class="lane-heading"><span class="stage-icon" data-icon>${icon(stage.icon)}</span><h2 id="stage-${index}">${stage.name}</h2><span class="lane-count" aria-label="${group.length} jobs">${group.length}</span></div>
        <div class="card-list">${group.length ? group.map((job) => card(job, now)).join("") : '<p class="empty-lane">No jobs in this stage</p>'}</div>
      </section>`;
    }).join("")}</div>`;
  }

  if (focusedAction) {
    const updated = board.querySelector(`[data-job="${focused}"]`);
    (updated?.querySelector(`[data-action="${focusedAction}"]`) ?? updated?.querySelector('[data-action="edit"]') ?? $("filter")).focus({ preventScroll: true });
  }
}

function renderQueue(now, open) {
  const rows = open.slice().sort(compareOrders);
  const groups = stages.map((stage, index) => {
    const group = rows.filter((job) => job.stage === index);
    if (!group.length) return "";
    return `<section class="queue-group stage-${index}">
      <h3>${stage.action}</h3>
      <table aria-label="${stage.action}">
        <thead><tr><th scope="col">Job</th><th scope="col">Due</th><th scope="col">Ordered</th><th scope="col">Outstanding</th></tr></thead>
        <tbody>${group.map((job) => `<tr>
          <td><span class="job-ref">${ref(job)}</span> <span class="queue-job-name">${escapeHtml(job.title)}</span>${job.notes ? `<span class="queue-note">${escapeHtml(job.notes)}</span>` : ""}</td>
          <td${isOverdue(job, now) ? ' class="queue-late"' : ""}><time datetime="${job.due}">${dueText(job, true)}</time>${isOverdue(job, now) ? "<br>Overdue" : ""}</td>
          <td>${number.format(job.quantity)}</td><td>${number.format(outstanding(job))}</td>
        </tr>`).join("")}</tbody>
      </table>
    </section>`;
  }).join("");
  $("queue").innerHTML = `<div class="queue-sheet"><header class="queue-heading"><div><h2 id="queue-title">Daily queue</h2><p>${fullDay.format(now)} · All open jobs, earliest due first within each group</p></div></header>
    ${groups || '<p>No open jobs to act on.</p>'}</div>`;
}

function render(now = new Date()) {
  lastRenderAt = now;
  const open = jobs.filter((job) => outstanding(job) > 0);
  $("today").textContent = fullDay.format(now);
  $("open-total").textContent = number.format(open.length);
  $("pickup-total").textContent = number.format(open.filter((job) => job.stage === 4).length);
  $("overdue-total").textContent = number.format(open.filter((job) => isOverdue(job, now)).length);
  $("copy-total").textContent = number.format(open.reduce((total, job) => total + outstanding(job), 0));
  renderBoard(now);
  renderQueue(now, open);
}

function refreshDeadlines() {
  const now = new Date();
  if (dateKey(now) !== dateKey(lastRenderAt) ||
      jobs.some((job) => isOverdue(job, now) !== isOverdue(job, lastRenderAt))) {
    render(now);
  }
}

function setView(view) {
  document.body.dataset.view = view;
  $("board-tab").setAttribute("aria-pressed", String(view === "board"));
  $("queue-tab").setAttribute("aria-pressed", String(view === "queue"));
  $("filters").hidden = view === "queue";
}

function setError(id, message = "") {
  const error = $(id);
  error.textContent = message;
  error.hidden = message === "";
}

function openJobForm(job = null) {
  editing = job;
  jobForm.reset();
  const fields = jobForm.elements;
  const collected = job ? handedOver(job) : 0;
  $("job-dialog-title").textContent = job ? "Edit job " + ref(job) : "New job";
  $("save-job").textContent = job ? "Save changes" : "Add job";
  fields.title.value = job?.title ?? "";
  fields.quantity.min = String(Math.max(1, collected));
  fields.quantity.value = job?.quantity ?? "";
  fields.stage.value = job?.stage ?? 0;
  fields.stage.disabled = Boolean(job && outstanding(job) === 0);
  fields.date.value = job?.due.slice(0, 10) ?? dateKey(new Date());
  fields.time.value = job?.due.slice(11) ?? "";
  fields.notes.value = job?.notes ?? "";
  const history = $("pickup-history");
  history.hidden = collected === 0;
  history.innerHTML = collected === 0 ? "" : `<details><summary>Pickup history · ${number.format(collected)} handed over</summary><ul>${job.pickups.map((entry) =>
    `<li>${number.format(entry.copies)} copies · ${timestamp.format(new Date(entry.at))}</li>`).join("")}</ul></details>`;
  setError("job-error");
  jobDialog.showModal();
}

jobForm.addEventListener("submit", async (event) => {
  event.preventDefault();
  const fields = jobForm.elements;
  const title = fields.title.value.trim();
  const quantity = fields.quantity.valueAsNumber;
  const stage = Number(fields.stage.value);
  const due = fields.date.value + "T" + fields.time.value;
  const notes = fields.notes.value.trim();
  const original = editing;
  const dueDate = new Date(due);
  setError("job-error");
  if (!title) {
    setError("job-error", "Enter a job name.");
    fields.title.focus();
    return;
  }
  if (!Number.isFinite(dueDate.getTime()) || dateKey(dueDate) !== fields.date.value ||
      dueDate.toTimeString().slice(0, 5) !== fields.time.value) {
    setError("job-error", "Choose a valid local date and time.");
    fields.time.focus();
    return;
  }
  let savedId;

  try {
    await updateOrders((current) => {
      const job = original && current.find((entry) => entry.id === original.id);
      if (original && (!job || JSON.stringify(job) !== JSON.stringify(original))) {
        throw new Error("This job changed in another window. Close and reopen it to see the latest details.");
      }
      const collected = job ? handedOver(job) : 0;
      if (!Number.isInteger(quantity) || quantity < Math.max(1, collected) || quantity > 9999999) {
        throw new Error("Enter a whole copy count from " + Math.max(1, collected) + " to 9,999,999.");
      }
      if (!stages[stage]) throw new Error("Choose a valid stage.");
      savedId = job?.id ?? current.reduce((max, entry) => Math.max(max, entry.id), 0) + 1;
      const updated = { id: savedId, title, quantity, stage: quantity === collected ? 4 : stage, due, notes, pickups: job?.pickups ?? [] };
      return job ? current.map((entry) => entry.id === savedId ? updated : entry) : [...current, updated];
    }, event.submitter);
    if (!original) {
      setView("board");
      $("filter").value = "open";
      $("search").value = "";
    }
    jobDialog.close();
    render();
    $("board").querySelector(`[data-job="${savedId}"] [data-action="edit"]`)?.focus({ preventScroll: true });
    report(original ? "Job updated." : "Job added.");
  } catch (error) {
    setError("job-error", error.message);
  }
});

function openPickupForm(job) {
  collecting = job;
  pickupForm.reset();
  const left = outstanding(job);
  pickupForm.elements.copies.max = String(left);
  $("pickup-context").textContent = `${job.title} · ${number.format(left)} of ${number.format(job.quantity)} copies outstanding`;
  setError("pickup-error");
  pickupDialog.showModal();
}

pickupForm.addEventListener("submit", async (event) => {
  event.preventDefault();
  const copies = pickupForm.elements.copies.valueAsNumber;
  const id = collecting.id;
  let left;
  setError("pickup-error");
  try {
    await updateOrders((current) => {
      const job = current.find((entry) => entry.id === id);
      if (!job || job.stage !== 4 || outstanding(job) === 0) {
        throw new Error("This job is no longer awaiting pickup. Close this window to see the latest board.");
      }
      const available = outstanding(job);
      if (!Number.isInteger(copies) || copies < 1 || copies > available) {
        pickupForm.elements.copies.max = String(available);
        $("pickup-context").textContent = `${job.title} · ${number.format(available)} of ${number.format(job.quantity)} copies outstanding`;
        throw new Error(`Enter a whole number from 1 to ${number.format(available)}.`);
      }
      left = available - copies;
      const updated = { ...job, pickups: [...job.pickups, { copies, at: new Date().toISOString() }] };
      return current.map((entry) => entry.id === id ? updated : entry);
    }, event.submitter);
    pickupDialog.close();
    render();
    ($("board").querySelector(`[data-job="${id}"] [data-action="pickup"]`) ?? $("filter")).focus({ preventScroll: true });
    report(left === 0 ? "Pickup complete." : `Pickup saved. ${number.format(left)} copies outstanding.`);
  } catch (error) {
    setError("pickup-error", error.message);
  }
});

$("board").addEventListener("click", async (event) => {
  const button = event.target.closest("button[data-action]");
  if (!button) return;
  const id = Number(button.closest("[data-job]").dataset.job);
  const job = jobs.find((entry) => entry.id === id);
  if (!job) return;
  const action = button.dataset.action;
  if (action === "edit") return openJobForm(job);
  if (action === "pickup") return openPickupForm(job);

  const nextStage = job.stage + (action === "next" ? 1 : -1);
  try {
    await updateOrders((current) => {
      const latest = current.find((entry) => entry.id === id);
      if (!latest || latest.stage !== job.stage || outstanding(latest) === 0) {
        throw new Error("This job changed in another window. The board has been refreshed.");
      }
      return current.map((entry) => entry.id === id ? { ...entry, stage: nextStage } : entry);
    });
    render();
    report("Moved to " + stages[nextStage].name + ".");
  } catch (error) {
    refreshOrders();
    report(error.message);
  }
});

document.querySelectorAll("[data-icon]").forEach((element) => { element.innerHTML = icon(element.dataset.icon); });
document.querySelectorAll("[data-close]").forEach((button) => { button.onclick = () => button.closest("dialog").close(); });
jobForm.elements.stage.replaceChildren(...stages.map((stage, index) => new Option(stage.name, index)));

$("board-tab").onclick = () => setView("board");
$("queue-tab").onclick = () => { render(); setView("queue"); };
$("new-job").onclick = () => openJobForm();
$("print-button").onclick = () => { render(); window.print(); };
$("filter").onchange = () => renderBoard(new Date());
$("search").oninput = () => renderBoard(new Date());

window.addEventListener("beforeprint", refreshOrders);
window.addEventListener("storage", (event) => {
  if (event.key === storageKey) refreshOrders();
});
document.addEventListener("visibilitychange", () => { if (!document.hidden) refreshOrders(); });
setInterval(refreshDeadlines, 15000);

setView("board");
initialize();
render();

:root {
  color-scheme: light;
  font-family: "Avenir Next", "Segoe UI", system-ui, sans-serif;
  color: #211d32;
  background: #f8f8fc;
  --ink: #211d32;
  --muted: #605a71;
  --line: #e5e1ee;
  --paper: #fff;
  --accent: #5035aa;
  --accent-dark: #40278f;
  --overdue: #a72745;
  --pink: #fff0f3;
  --number: ui-monospace, "SFMono-Regular", Consolas, monospace;
}
* { box-sizing: border-box; }
body { margin: 0; }
[hidden] { display: none !important; }
button, input, select, textarea { font: inherit; }
button, select { cursor: pointer; }
button { color: inherit; }
button, input, select, textarea { transition: background-color .16s, border-color .16s; }
:focus-visible { outline: 3px solid #7155ce; outline-offset: 3px; }
svg { width: 18px; height: 18px; display: block; }
[data-icon] { display: inline-flex; flex-shrink: 0; align-items: center; justify-content: center; }
.shell { width: min(100% - 80px, 1512px); margin-inline: auto; }
.topbar { background: #fff; border-bottom: 1px solid var(--line); }
.topbar-inner { min-height: 70px; display: flex; justify-content: space-between; align-items: center; gap: 16px; }
.brand { display: flex; align-items: center; gap: 11px; font-size: 20px; line-height: 1; font-weight: 750; letter-spacing: -.035em; }
.brand-icon { width: 36px; height: 36px; border-radius: 11px; color: white; background: var(--accent); }
.brand-icon svg { width: 20px; height: 20px; }
.local-status { display: inline-flex; gap: 8px; align-items: center; color: #4e5261; font-size: 13px; font-weight: 650; }
.local-status i { width: 8px; height: 8px; border-radius: 50%; background: #348466; box-shadow: 0 0 0 3px #e7f3ed; }
.local-status.error i { background: var(--overdue); box-shadow: 0 0 0 3px var(--pink); }
.intro { display: flex; align-items: end; justify-content: space-between; gap: 20px; padding-block: 34px 26px; }
.date-line { margin: 0 0 7px; color: var(--accent); font-family: var(--number); text-transform: uppercase; letter-spacing: .075em; font-size: 12px; font-weight: 700; }
h1 { margin: 0; font-size: clamp(43px, 6vw, 64px); line-height: .99; font-weight: 760; letter-spacing: -.075em; }
.intro-copy { margin: 12px 0 0; color: var(--muted); font-size: 15px; }
.header-actions, .dialog-actions { display: flex; flex-wrap: wrap; gap: 10px; }
.button, .icon-button { min-height: 44px; border-radius: 9px; border: 1px solid transparent; display: inline-flex; justify-content: center; align-items: center; gap: 8px; padding: 0 14px; font-size: 14px; font-weight: 700; text-decoration: none; }
.primary { background: var(--accent); color: white; border-color: var(--accent); }
.primary:hover { background: var(--accent-dark); }
.secondary, .icon-button { background: var(--paper); color: var(--ink); border-color: var(--line); }
.secondary:hover, .icon-button:hover { background: #f0ebfb; border-color: #d4c7f0; }
.icon-button { width: 44px; padding: 0; }
.overview { display: grid; grid-template-columns: repeat(4, 1fr); background: #fff; border: 1px solid var(--line); border-radius: 13px; box-shadow: 0 2px 4px #25144806; }
.metric { display: flex; align-items: center; gap: 13px; padding: 17px 20px; min-width: 0; }
.metric + .metric { border-left: 1px solid var(--line); }
.metric-icon { width: 42px; height: 42px; border-radius: 10px; }
.metric-icon.ink { background: #efe9ff; color: var(--accent); }
.metric-icon.green { background: #e4f3ec; color: #23674e; }
.metric-icon.red { background: var(--pink); color: var(--overdue); }
.metric-icon.blue { background: #e9effd; color: #35569d; }
.metric div > span { display: block; color: var(--muted); font-size: 13px; font-weight: 650; }
.metric strong { display: block; margin-top: 2px; font-family: var(--number); font-size: 25px; line-height: 1.05; letter-spacing: -.05em; overflow-wrap: anywhere; }
.toolbar { display: flex; justify-content: space-between; align-items: center; gap: 12px; padding-block: 25px 15px; }
.view-switch { display: flex; gap: 4px; padding: 4px; background: #eeecf5; border: 1px solid var(--line); border-radius: 10px; }
.view-button { min-height: 44px; border-radius: 7px; border: 1px solid transparent; display: inline-flex; gap: 7px; align-items: center; background: transparent; color: var(--muted); padding: 0 12px; font-size: 14px; font-weight: 700; }
.view-button[aria-pressed="true"] { color: var(--accent); background: #fff; border-color: #e3dbee; box-shadow: 0 1px 3px #23144212; }
.view-button:hover { color: var(--accent); background: #f9f7ff; }
.filters { display: flex; align-items: center; gap: 9px; min-width: 0; }
.search { display: flex; align-items: center; gap: 8px; padding: 0 11px; color: var(--muted); }
.search, .filter-select { min-height: 44px; border-radius: 9px; border: 1px solid var(--line); background-color: white; font-size: 14px; }
.search:focus-within { outline: 3px solid #7155ce; outline-offset: 2px; }
.search input { min-width: 0; width: 170px; border: 0; background: transparent; outline: none; padding: 9px 0; color: var(--ink); }
.search input:focus-visible { outline: none; }
.search input::placeholder { color: var(--muted); }
.filter-select { padding: 0 12px; color: var(--ink); }
.board-grid { display: grid; grid-template-columns: repeat(5, minmax(0, 1fr)); gap: 12px; align-items: stretch; }
.lane { border: 1px solid var(--lane-line); border-radius: 12px; background: var(--lane-bg); min-width: 0; min-height: 365px; padding: 0 9px 10px; }
.stage-0 { --lane-bg: #f1f0f6; --lane-line: #e4e0ed; --stage-ink: #59516f; --stage-fill: #e6e2ef; }
.stage-1 { --lane-bg: #f3edf9; --lane-line: #e8dff1; --stage-ink: #6b398a; --stage-fill: #eadcf5; }
.stage-2 { --lane-bg: #edf1fb; --lane-line: #dfe6f5; --stage-ink: #35538f; --stage-fill: #dfe8fa; }
.stage-3 { --lane-bg: #faf2e6; --lane-line: #efe3d1; --stage-ink: #865215; --stage-fill: #f4e5cd; }
.stage-4 { --lane-bg: #eaf3ef; --lane-line: #d9ebe2; --stage-ink: #25664e; --stage-fill: #d9ece2; }
.lane-heading { display: flex; gap: 8px; align-items: center; padding: 13px 3px 12px; color: var(--stage-ink); }
.lane-heading h2 { margin: 0; font-size: 14px; font-weight: 750; line-height: 1.2; }
.stage-icon { width: 30px; height: 30px; border-radius: 8px; background: var(--stage-fill); }
.stage-icon svg { width: 16px; height: 16px; }
.lane-count { margin-left: auto; min-width: 24px; text-align: center; padding: 2px 4px; border-radius: 6px; background: var(--stage-fill); font: 700 12px/1.5 var(--number); }
.card-list { display: grid; gap: 9px; }
.empty-lane { text-align: center; border: 1px dashed var(--lane-line); border-radius: 8px; margin: 0; color: var(--muted); padding: 24px 5px; font-size: 13px; }
.job-card { position: relative; border: 1px solid var(--line); border-radius: 10px; background: #fff; min-width: 0; overflow: clip; box-shadow: 0 2px 3px #21123308; }
.job-card.late { border-color: #e9b4c0; }
.job-card.late::before { content: ""; position: absolute; inset: 0 auto 0 0; width: 3px; background: #bf4260; }
.job-body { padding: 12px 11px; }
.job-meta { display: flex; align-items: center; justify-content: space-between; flex-wrap: wrap; gap: 4px; }
.job-ref { color: var(--muted); font: 650 11px/1.4 var(--number); letter-spacing: .025em; }
.late-label { display: inline-flex; align-items: center; gap: 4px; font-size: 11px; font-weight: 750; color: var(--overdue); background: var(--pink); padding: 3px 6px; border-radius: 5px; }
.late-label svg { width: 12px; height: 12px; }
.job-title { margin: 5px 0 6px; font-size: 17px; line-height: 1.25; letter-spacing: -.025em; }
.title-button { display: block; padding: 6px 0; margin: -2px 0; min-height: 44px; border: 0; background: transparent; text-align: left; font: inherit; font-weight: 750; overflow-wrap: anywhere; }
.title-button:hover { color: var(--accent); text-decoration: underline; }
.due { display: flex; align-items: center; gap: 6px; color: var(--muted); font-size: 12px; font-weight: 650; min-height: 22px; }
.due svg { width: 14px; height: 14px; }
.late .due { color: var(--overdue); }
.quantity { border-top: 1px solid #eeeaf4; margin-top: 10px; padding-top: 9px; display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 5px; }
.quantity span { display: block; color: var(--muted); font-size: 11px; font-weight: 650; }
.quantity strong { display: block; font: 700 18px/1.3 var(--number); overflow-wrap: anywhere; }
.card-actions { display: flex; align-items: stretch; gap: 5px; padding: 7px; border-top: 1px solid var(--line); background: #fcfbfe; }
.card-actions .icon-button { width: 44px; flex: 0 0 44px; }
.card-actions .button { flex: 1; font-size: 12px; padding: 0 6px; gap: 4px; }
.card-actions svg { width: 15px; height: 15px; }
.card-actions .secondary { color: var(--accent); }
.card-actions .handover { background: #e5f2ec; border-color: #d5e9df; color: #235c47; }
.card-actions .handover:hover { background: #d5eddf; }
.completed-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(min(100%, 230px), 1fr)); gap: 12px; }
.completed-title { margin: 0 0 12px; font-size: 20px; }
.section-empty, .queue-sheet { background: white; border: 1px solid var(--line); border-radius: 12px; padding: 26px; }
.section-empty { color: var(--muted); }
.footer { border-top: 1px solid var(--line); margin-block: 20px; padding-top: 14px; font-size: 12px; font-weight: 650; color: var(--muted); }
.footer span { display: inline-flex; align-items: center; gap: 7px; }
.footer svg { width: 15px; height: 15px; }
.queue-heading { display: flex; justify-content: space-between; align-items: start; gap: 12px; flex-wrap: wrap; }
.queue-heading h2 { margin: 0; letter-spacing: -.035em; font-size: 29px; }
.queue-heading p { margin: 5px 0 0; color: var(--muted); font-size: 14px; }
.queue-group { margin: 24px 0 0; }
.queue-group h3 { color: var(--stage-ink); background: var(--lane-bg); padding: 9px 12px; border-radius: 6px; margin: 0; font-size: 15px; }
.queue-group table { width: 100%; table-layout: fixed; border-collapse: collapse; font-size: 14px; }
.queue-group th, .queue-group td { padding: 9px 10px; border-bottom: 1px solid var(--line); overflow-wrap: anywhere; vertical-align: top; }
.queue-group th { text-align: left; color: var(--muted); font-size: 12px; }
.queue-group th:first-child { width: 46%; }
.queue-group th:nth-child(2) { width: 26%; }
.queue-group th:nth-child(n+3), .queue-group td:nth-child(n+3) { text-align: right; }
.queue-job-name { display: block; font-weight: 750; }
.queue-note { display: block; white-space: pre-wrap; color: var(--muted); }
.queue-group .queue-late { color: var(--overdue); font-weight: 700; }
dialog { width: min(500px, calc(100% - 28px)); max-height: calc(100% - 28px); padding: 0; border: 1px solid var(--line); background: #fff; color: var(--ink); border-radius: 15px; box-shadow: 0 20px 70px #20173845; }
dialog::backdrop { background: #221b3a70; }
dialog form { padding: 21px; display: grid; gap: 14px; }
.dialog-heading { display: flex; justify-content: space-between; align-items: center; gap: 12px; }
.dialog-heading h2 { margin: 0; font-size: 26px; letter-spacing: -.04em; }
dialog p { margin: 0; color: var(--muted); }
dialog label { display: block; min-width: 0; font-size: 14px; font-weight: 700; }
dialog small { color: var(--muted); font-weight: 500; }
dialog input, dialog select, dialog textarea { display: block; width: 100%; min-width: 0; min-height: 44px; border: 1px solid #cbc3db; border-radius: 8px; padding: 8px; background: white; color: var(--ink); margin-top: 5px; font-size: 16px; }
dialog textarea { resize: vertical; }
.form-row { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 12px; }
.dialog-actions { justify-content: end; }
.form-error { color: var(--overdue); }
#pickup-history { color: var(--muted); font-size: 13px; }
#pickup-history summary { cursor: pointer; font-weight: 700; padding-block: 6px; }
#pickup-history ul { margin: 4px 0; padding-left: 21px; }
.notice { position: fixed; z-index: 2; bottom: 12px; right: 16px; max-width: calc(100% - 32px); margin: 0; padding: 12px 16px; border-radius: 9px; background: var(--ink); color: white; box-shadow: 0 4px 20px #21123335; font-size: 14px; }
body[data-view="board"] #queue, body[data-view="queue"] #board { display: none; }
@media (max-width: 1100px) {
  .shell { width: calc(100% - 40px); }
  .board-grid { gap: 7px; }
  .lane { padding-inline: 6px; }
  .lane-heading { gap: 5px; }
  .metric { padding-inline: 13px; }
}
@media (max-width: 920px) {
  .board-grid { grid-template-columns: repeat(3, minmax(0, 1fr)); }
  .lane { min-height: 235px; }
}
@media (max-width: 660px) {
  .shell { width: calc(100% - 28px); }
  .topbar-inner { min-height: 60px; }
  .intro { align-items: start; flex-direction: column; padding-top: 25px; }
  .toolbar { align-items: stretch; flex-direction: column; }
  .view-switch { align-self: start; }
  .search { flex: 1; }
  .search input { width: 100%; }
  .overview { grid-template-columns: repeat(2, 1fr); }
  .metric { padding: 11px 8px; gap: 8px; }
  .metric:nth-child(3) { border-left: 0; }
  .metric:nth-child(n+3) { border-top: 1px solid var(--line); }
  .metric-icon { width: 34px; height: 34px; }
  .board-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .lane { min-height: auto; }
  .queue-sheet { padding: 13px; }
  .queue-group th, .queue-group td { padding-inline: 4px; }
  .queue-group table { font-size: 13px; }
}
@media (max-width: 405px) {
  .board-grid { grid-template-columns: minmax(0, 1fr); }
}
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { transition: none !important; }
}
@page { margin: 13mm; }
@media print {
  :root, body { background: white; color: black; }
  .topbar, .intro, .overview, .toolbar, #board, .footer, .notice, dialog, noscript { display: none !important; }
  #queue { display: block !important; }
  .shell { width: 100%; }
  .queue-sheet { border: 0; padding: 0; }
  .queue-heading h2 { font-size: 24pt; }
  .queue-heading p, .queue-note, .queue-group th, .queue-group .queue-late { color: #222; }
  .queue-group { margin-top: 14pt; }
  .queue-group h3 { color: black; background: white; padding: 0 0 5pt; border-bottom: 1.5pt solid #222; border-radius: 0; break-after: avoid; }
  .queue-group table { font-size: 10pt; }
  .queue-group th, .queue-group td { border-color: #bbb; padding: 5pt; }
  .queue-group tr { break-inside: avoid; }
  .queue-group thead { display: table-header-group; break-after: avoid; }
}
